  { q:"ある商品を定価の15%引きで売ったところ、利益は原価の2%になった。定価は原価の何倍か。", choices:["1.02倍","1.2倍","1.25倍","1.15倍"], answer:1, exp:"定価×0.85=原価×1.02より、定価=原価×1.2倍。" },
  { q:"ある商品を定価の25%引きで売ったところ、利益は原価の10%になった。定価は原価の何倍か。", choices:["1.417倍","1.1倍","1.467倍","1.517倍"], answer:2, exp:"定価×0.75=原価×1.1より、定価=原価×1.467倍。" },
  { q:"原価3000円の商品に4割の利益を見込んで定価をつけたが、売れなかったため定価の2割引きで販売した。売価はいくらか。", choices:["4200円","3000円","3600円","3360円"], answer:3, exp:"定価=3000×1.4=4200円。売価=4200×0.8=3360円。" },
  { q:"ある店で、原価の20%の利益を見込んで定価をつけた商品を、定価の1割引きで販売したところ、利益は480円になった。原価はいくらか。", choices:["6000円","5800円","6200円","5500円"], answer:0, exp:"原価をxとすると、x×1.2×0.9-x=480より、0.08x=480、x=6000円。" },
  { q:"定価4000円の商品を3割引きで販売しても、なお原価の12%の利益が出るという。この商品の原価はいくらか。", choices:["2400円","2500円","2800円","2600円"], answer:1, exp:"定価×0.7=原価×1.12より、原価=4000×0.7/1.12=2500円。" }
