{ group:"非言語", id:"sokudo", name:"速度算", desc:"速さ・時間・距離。旅人算なども含む", questions:[
  { q:"時速60kmで3時間走ったときの走行距離は何kmか。", choices:["180km","200km","240km","150km"], answer:0, exp:"60km/時×3時間=180km。" },
  { q:"家から駅まで2.4kmの道のりを分速80mで歩くと何分かかるか。", choices:["24分","30分","40分","20分"], answer:1, exp:"2.4km=2400m。2400m÷80m/分=30分。" },
  { q:"A地点からB地点まで240kmの距離を、行きは時速60km、帰りは時速40kmで往復した。往復の平均速度は時速何kmか。", choices:["52km","45km","48km","50km"], answer:2, exp:"行き4時間、帰り6時間、合計480km÷10時間=時速48km。" },
  { q:"A地点からB地点までの距離は18kmである。時速4.5kmで歩くと何時間かかるか。", choices:["4.5時間","5時間","3時間","4時間"], answer:3, exp:"18÷4.5=4時間。" },
  { q:"兄は分速150mで、弟は分速100mで同じ地点から同時に反対方向に歩き始めた。10分後の2人の間の距離は何mか。", choices:["2500m","3000m","1500m","2000m"], answer:0, exp:"(150+100)×10=2500m。" },
  { q:"電車が160kmの距離を2時間で走った。この電車の速さは時速何kmか。", choices:["75km","80km","90km","70km"], answer:1, exp:"160÷2=時速80km。" },
  { q:"A君は分速80mで歩き、B君はA君の10分後に同じ地点から分速120mで追いかけた。B君がA君に追いつくのは、B君が出発してから何分後か。", choices:["30分","15分","20分","25分"], answer:2, exp:"A君は10分で800m先行。速度差40m/分。800÷40=20分。" },
  { q:"池の周囲を1周する道のりは3.6kmである。この道のりを時速7.2kmで1周するのに何分かかるか。", choices:["40分","20分","25分","30分"], answer:3, exp:"3.6÷7.2=0.5時間=30分。" },
  { q:"上りは時速4km、下りは時速6kmで同じ道を往復した。往復にかかった時間の合計が5時間のとき、片道の距離は何kmか。", choices:["12km","15km","8km","10km"], answer:0, exp:"x/4+x/6=5より、5x/12=5、x=12km。" },
  { q:"長さ150mの列車が秒速25mで走るとき、長さ350mの鉄橋を渡り終えるまでに何秒かかるか。", choices:["18秒","20秒","25秒","14秒"], answer:1, exp:"走行距離=350+150=500m。500÷25=20秒。" },
  { q:"時速45kmで4時間走ったときの走行距離は何kmか。", choices:["225km","360km","180km","135km"], answer:2, exp:"45km/時×4時間=180km。" },
  { q:"時速72kmで2.5時間走ったときの走行距離は何kmか。", choices:["108km","252km","360km","180km"], answer:3, exp:"72km/時×2.5時間=180km。" },
  { q:"家から公園まで1.6kmの道のりを分速80mで歩くと何分かかるか。", choices:["20分","15分","25分","30分"], answer:0, exp:"1.6km=1600.0m。1600.0m÷80m/分=20分。" },
  { q:"家から公園まで3.0kmの道のりを分速120mで歩くと何分かかるか。", choices:["35分","25分","20分","30分"], answer:1, exp:"3.0km=3000.0m。3000.0m÷120m/分=25分。" },
  { q:"A地点からB地点まで300kmの距離を、行きは時速50km、帰りは時速30kmで往復した。往復の平均速度は時速何kmか。", choices:["43km","33km","38km","40km"], answer:2, exp:"行き6時間、帰り10時間、合計600km÷16時間=時速38km。" },
  { q:"A地点からB地点まで180kmの距離を、行きは時速60km、帰りは時速90kmで往復した。往復の平均速度は時速何kmか。", choices:["75km","77km","67km","72km"], answer:3, exp:"行き3時間、帰り2時間、合計360km÷5時間=時速72km。" },
  { q:"A地点からB地点までの距離は28kmである。時速3.5kmで進むと何時間かかるか。", choices:["8時間","9時間","7時間","16時間"], answer:0, exp:"28÷3.5=8時間。" },
  { q:"A地点からB地点までの距離は15kmである。時速7.5kmで進むと何時間かかるか。", choices:["4時間","2時間","3時間","1時間"], answer:1, exp:"15÷7.5=2時間。" },
  { q:"姉は分速120mで、妹は分速90mで同じ地点から同時に反対方向に歩き始めた。15分後の2人の間の距離は何mか。", choices:["3300m","1575m","3150m","1350m"], answer:2, exp:"(120+90)×15=3150m。" },
  { q:"姉は分速200mで、妹は分速150mで同じ地点から同時に反対方向に歩き始めた。8分後の2人の間の距離は何mか。", choices:["1200m","2880m","1400m","2800m"], answer:3, exp:"(200+150)×8=2800m。" },
  { q:"新幹線が600kmの距離を2時間で走った。この新幹線の速さは時速何kmか。", choices:["300km","310km","290km","320km"], answer:0, exp:"600÷2=時速300km。" },
  { q:"新幹線が490kmの距離を3.5時間で走った。この新幹線の速さは時速何kmか。", choices:["160.0km","140.0km","150.0km","130.0km"], answer:1, exp:"490÷3.5=時速140.0km。" },
  { q:"兄は分速70mで歩き、弟は兄の15分後に同じ地点から分速140mで追いかけた。弟が兄に追いつくのは、弟が出発してから何分後か。", choices:["20分","25分","15分","10分"], answer:2, exp:"兄は15分で1050m先行。速度差70m/分。1050÷70=15分。" },
  { q:"兄は分速90mで歩き、弟は兄の8分後に同じ地点から分速150mで追いかけた。弟が兄に追いつくのは、弟が出発してから何分後か。", choices:["7分","17分","22分","12分"], answer:3, exp:"兄は8分で720m先行。速度差60m/分。720÷60=12分。" },
  { q:"池の周囲を1周する道のりは4.8kmである。この道のりを時速9.6kmで1周するのに何分かかるか。", choices:["30分","20分","40分","50分"], answer:0, exp:"4.8÷9.6=0.5時間=30分。" },
  { q:"池の周囲を1周する道のりは2.4kmである。この道のりを時速4.8kmで1周するのに何分かかるか。", choices:["50分","30分","20分","40分"], answer:1, exp:"2.4÷4.8=0.5時間=30分。" },
  { q:"上りは時速3km、下りは時速5kmで同じ道を往復した。往復にかかった時間の合計が16時間のとき、片道の距離は何kmか。", choices:["35km","40km","30km","25km"], answer:2, exp:"x/3+x/5=16より、x=30km。" },
  { q:"上りは時速6km、下りは時速9kmで同じ道を往復した。往復にかかった時間の合計が10時間のとき、片道の距離は何kmか。", choices:["31km","41km","46km","36km"], answer:3, exp:"x/6+x/9=10より、x=36km。" },
  { q:"長さ120mの列車が秒速20mで走るとき、長さ480mの鉄橋を渡り終えるまでに何秒かかるか。", choices:["30秒","26秒","34秒","38秒"], answer:0, exp:"走行距離=480+120=600m。600÷20=30秒。" },
  { q:"長さ200mの列車が秒速40mで走るとき、長さ600mの鉄橋を渡り終えるまでに何秒かかるか。", choices:["28秒","20秒","16秒","24秒"], answer:1, exp:"走行距離=600+200=800m。800÷40=20秒。" }
]},
{ group:"非言語", id:"shugo", name:"集合", desc:"ベン図を使った集合の問題", questions:[
  { q:"ある学年の生徒40人にアンケートをとったところ、犬を飼っている人は18人、猫を飼っている人は15人、どちらも飼っていない人は12人だった。犬と猫の両方を飼っている人は何人か。", choices:["5人","7人","10人","3人"], answer:0, exp:"少なくとも一方を飼う人は40-12=28人。18+15-28=5人。" },
  { q:"生徒50人のうち、数学が得意な人は30人、英語が得意な人は25人、両方とも得意な人は12人いる。どちらも得意でない人は何人か。", choices:["5人","7人","9人","12人"], answer:1, exp:"少なくとも一方が得意な人は30+25-12=43人。50-43=7人。" },
  { q:"100人にアンケートしたところ、Aサービス利用者は45人、Bサービス利用者は38人、両方利用している人は15人だった。どちらも利用していない人は何人か。", choices:["22人","28人","32人","38人"], answer:2, exp:"少なくとも一方利用は45+38-15=68人。100-68=32人。" },
  { q:"生徒60人のうち、部活動Aに所属する人は28人、部活動Bに所属する人は25人、両方に所属する人は9人いる。どちらにも所属していない人は何人か。", choices:["20人","12人","14人","16人"], answer:3, exp:"少なくとも一方に所属は28+25-9=44人。60-44=16人。" },
  { q:"30人のクラスで、犬派は20人、猫派は15人、犬も猫も好きな人は8人いた。犬も猫も好きではない人は何人か。", choices:["3人","5人","7人","2人"], answer:0, exp:"少なくとも一方好きは20+15-8=27人。30-27=3人。" },
  { q:"あるアンケートで、コーヒーを飲む人は65人、紅茶を飲む人は48人、両方飲む人は30人、どちらも飲まない人は12人だった。アンケートに回答した人は全部で何人か。", choices:["90人","95人","101人","83人"], answer:1, exp:"回答者数=65+48-30+12=95人。" },
  { q:"40人のクラスで、数学のテストに合格した人は25人、英語のテストに合格した人は20人だった。少なくとも一方に合格した人が32人のとき、両方合格した人は何人か。", choices:["8人","10人","13人","15人"], answer:2, exp:"両方合格=25+20-32=13人。" },
  { q:"生徒50人に旅行先の希望を聞いたところ、海外希望が32人、国内希望が28人、どちらも希望しない人は5人だった。海外と国内の両方を希望する人は何人か。", choices:["20人","10人","12人","15人"], answer:3, exp:"少なくとも一方希望は50-5=45人。32+28-45=15人。" },
  { q:"あるクラス36人のうち、野球が好きな人はサッカーが好きな人より6人多く、両方好きな人は10人、どちらも好きでない人は4人いた。野球が好きな人数は何人か。", choices:["24人","16人","18人","20人"], answer:0, exp:"野球x、サッカーx-6として、x+(x-6)-10=36-4より2x-16=32、x=24人。" },
  { q:"生徒45人のうち、通学に電車を使う人は30人、バスを使う人は22人、両方使う人は12人だった。電車もバスも使わない人は何人か。", choices:["3人","5人","7人","9人"], answer:1, exp:"少なくとも一方使用は30+22-12=40人。45-40=5人。" },
  { q:"生徒50人にアンケートをとったところ、野球部を応援している人は26人、サッカー部を応援している人は22人、どちらも応援していない人は10人だった。両方応援している人は何人か。", choices:["12人","6人","8人","10人"], answer:2, exp:"少なくとも一方は50-10=40人。26+22-40=8人。" },
  { q:"生徒36人のうち、スマホを持っている人は30人、タブレットを持っている人は18人、どちらも持っていない人は3人だった。両方持っている人は何人か。", choices:["18人","20人","12人","15人"], answer:3, exp:"少なくとも一方は36-3=33人。30+18-33=15人。" },
  { q:"70人にアンケートしたところ、朝食を毎日食べる人は48人、運動習慣がある人は35人、どちらも当てはまらない人は9人だった。両方当てはまる人は何人か。", choices:["22人","24人","18人","20人"], answer:0, exp:"少なくとも一方は70-9=61人。48+35-61=22人。" },
  { q:"生徒45人のうち、英検を持っている人は27人、TOEICを受けたことがある人は20人、両方とも経験のある人は9人いる。どちらも経験がない人は何人か。", choices:["5人","7人","9人","11人"], answer:1, exp:"少なくとも一方は27+20-9=38人。45-38=7人。" },
  { q:"生徒60人のうち、アルバイト経験がある人は38人、サークル活動をしている人は30人、両方とも当てはまる人は15人いる。どちらも当てはまらない人は何人か。", choices:["11人","5人","7人","9人"], answer:2, exp:"少なくとも一方は38+30-15=53人。60-53=7人。" },
  { q:"100人にアンケートしたところ、犬を飼ったことがある人は58人、猫を飼ったことがある人は42人、どちらも飼ったことがない人は22人だった。両方飼ったことがある人は何人か。", choices:["24人","26人","20人","22人"], answer:3, exp:"少なくとも一方は100-22=78人。58+42-78=22人。" },
  { q:"生徒80人のうち、数学が好きな人は45人、理科が好きな人は38人、少なくとも一方が好きな人は63人だった。両方好きな人は何人か。", choices:["20人","22人","24人","18人"], answer:0, exp:"45+38-63=20人。" },
  { q:"生徒55人のうち、ピアノを習ったことがある人は28人、水泳を習ったことがある人は24人、少なくとも一方を習ったことがある人が41人のとき、両方習ったことがある人は何人か。", choices:["9人","11人","13人","15人"], answer:1, exp:"28+24-41=11人。" },
  { q:"生徒90人に旅行先の希望を聞いたところ、国内希望が52人、海外希望が40人、どちらも希望しない人は12人だった。国内と海外の両方を希望する人は何人か。", choices:["10人","12人","14人","16人"], answer:2, exp:"少なくとも一方は90-12=78人。52+40-78=14人。" },
  { q:"生徒54人のうち、朝型と答えた人は32人、夜型と答えた人は28人、どちらでもないと答えた人は0人だった。朝型・夜型の両方に近いと答えた人(重複回答)は何人か。", choices:["8人","10人","4人","6人"], answer:3, exp:"少なくとも一方(全員)54人。32+28-54=6人。" },
  { q:"120人にアンケートしたところ、Xアプリ利用者は72人、Yアプリ利用者は58人だった。両方利用している人が35人のとき、どちらも利用していない人は何人か。", choices:["25人","27人","29人","23人"], answer:0, exp:"少なくとも一方は72+58-35=95人。120-95=25人。" },
  { q:"あるクラス40人のうち、通学に自転車を使う人は22人、電車を使う人は20人、両方使う人は6人いる。どちらも使わない人は何人か。", choices:["2人","4人","6人","8人"], answer:1, exp:"少なくとも一方は22+20-6=36人。40-36=4人。" },
  { q:"生徒65人のうち、吹奏楽部経験者は30人、合唱部経験者は25人、両方の経験がある人は8人いる。どちらの経験もない人は何人か。", choices:["22人","16人","18人","20人"], answer:2, exp:"少なくとも一方は30+25-8=47人。65-47=18人。" },
  { q:"生徒52人のうち、朝ごはんにパンを食べる人は33人、ご飯を食べる人は26人、少なくとも一方を食べる人は47人だった。両方食べる人は何人か。", choices:["14人","16人","10人","12人"], answer:3, exp:"33+26-47=12人。" },
  { q:"110人にアンケートしたところ、Aブランド利用者は64人、Bブランド利用者は50人、どちらも利用していない人は18人だった。両方利用している人は何人か。", choices:["22人","24人","26人","20人"], answer:0, exp:"少なくとも一方は110-18=92人。64+50-92=22人。" },
  { q:"生徒75人のうち、部活動に所属している人は58人、委員会に所属している人は30人、どちらにも所属していない人は9人いる。両方に所属している人は何人か。", choices:["20人","22人","24人","26人"], answer:1, exp:"少なくとも一方は75-9=66人。58+30-66=22人。" },
  { q:"生徒38人のうち、朝練に参加する人は22人、夜練に参加する人は19人、両方参加する人は8人いる。どちらにも参加しない人は何人か。", choices:["9人","3人","5人","7人"], answer:2, exp:"少なくとも一方は22+19-8=33人。38-33=5人。" },
  { q:"95人にアンケートしたところ、通販アプリAを使う人は56人、通販アプリBを使う人は44人、どちらも使わない人は15人だった。両方使う人は何人か。", choices:["22人","24人","18人","20人"], answer:3, exp:"少なくとも一方は95-15=80人。56+44-80=20人。" },
  { q:"生徒42人のうち、朝食を家で食べる人は30人、弁当を持参する人は22人、両方に当てはまる人は14人いる。どちらにも当てはまらない人は何人か。", choices:["4人","6人","8人","2人"], answer:0, exp:"少なくとも一方は30+22-14=38人。42-38=4人。" },
  { q:"生徒40人のうち、動画配信サービスAを利用する人は24人、サービスBを利用する人は19人、どちらも利用しない人は7人だった。両方利用する人は何人か。", choices:["8人","10人","12人","14人"], answer:1, exp:"少なくとも一方は40-7=33人。24+19-33=10人。" }
]},
{ group:"非言語", id:"hyou", name:"表の読み取り", desc:"グラフや表からデータを読み取る問題", questions:[
  { q:"次の表は、ある店の月別売上(万円)である。\n4月:120　5月:150　6月:135　7月:180\n4月から7月までの売上の合計はいくらか。", choices:["585万円","600万円","610万円","565万円"], answer:0, exp:"120+150+135+180=585万円。" },
  { q:"次の表は、ある部活動の学年別人数である。\n1年:18人　2年:22人　3年:15人\n全体に占める2年生の割合は約何%か(小数点以下四捨五入)。", choices:["35%","40%","45%","30%"], answer:1, exp:"全体55人のうち2年22人。22/55=0.4=40%。" },
  { q:"次の表は、ある工場の製品A〜Dの月間生産数である。\nA:320個　B:280個　C:410個　D:190個\n生産数が2番目に多い製品はどれか。", choices:["C","D","A","B"], answer:2, exp:"多い順にC(410)>A(320)>B(280)>D(190)。2番目はA。" },
  { q:"次の表は、4支店の今月の来客数である。\n東:1200人　西:980人　南:1450人　北:870人\n4支店の来客数の平均は何人か。", choices:["1150人","1200人","1100人","1125人"], answer:3, exp:"合計4500人÷4=1125人。" },
  { q:"次の表は、ある商品の週別販売個数である。\n1週目:80個　2週目:95個　3週目:70個　4週目:105個\n前週比で最も販売個数が増加したのはどの週か。", choices:["4週目","変化なし","2週目","3週目"], answer:0, exp:"2週目+15個、3週目-25個、4週目+35個で、4週目の増加が最大。" },
  { q:"次の表は、あるクラスの小テストの得点分布である。\n80点以上:6人　60〜79点:14人　40〜59点:8人　39点以下:2人\nこのクラスの人数は全部で何人か。", choices:["28人","30人","32人","26人"], answer:1, exp:"6+14+8+2=30人。" },
  { q:"次の表は、ある会社の部署別従業員数(前年比)である。\n営業部:45人(前年40人)　開発部:60人(前年55人)　総務部:15人(前年18人)\n前年から人数が減少した部署はどれか。", choices:["営業部","開発部","総務部","変化なし"], answer:2, exp:"総務部のみ18人→15人と減少している。" },
  { q:"次の表は、ある都市の月別平均気温(℃)である。\n1月:5℃　4月:15℃　7月:28℃　10月:18℃\n1月と7月の気温差は何度か。", choices:["25度","18度","20度","23度"], answer:3, exp:"28-5=23度。" },
  { q:"次の表は、あるオンラインショップの商品カテゴリ別売上構成比である。\n衣料品:35%　食品:25%　家電:20%　その他:20%\n衣料品と食品を合わせた売上構成比は全体の何%か。", choices:["60%","65%","50%","55%"], answer:0, exp:"35+25=60%。" },
  { q:"次の表は、ある図書館の年代別利用者数である。\n10代:120人　20代:180人　30代:150人　40代以上:250人\n全利用者に占める40代以上の割合は約何%か(小数点以下四捨五入)。", choices:["約30%","約36%","約40%","約25%"], answer:1, exp:"合計700人のうち250人。250/700≈35.7%で約36%。" },
  { q:"次の表は、ある店の月別売上(万円)である。\n1月:95　2月:110　3月:125　4月:140\n1月から4月までの売上の合計はいくらか。", choices:["510万円","450万円","470万円","490万円"], answer:2, exp:"95+110+125+140=470万円。" },
  { q:"次の表は、あるサークルの学年別人数である。\n1年:24人　2年:16人　3年:20人\n全体に占める1年生の割合は約何%か(小数点以下四捨五入)。", choices:["45%","50%","35%","40%"], answer:3, exp:"全体60人のうち1年24人。24/60=0.4=40%。" },
  { q:"次の表は、ある工場の製品P〜Sの月間生産数である。\nP:280個　Q:350個　R:190個　S:410個\n生産数が最も少ない製品はどれか。", choices:["R","S","P","Q"], answer:0, exp:"少ない順にR(190)<P(280)<Q(350)<S(410)。最も少ないのはR。" },
  { q:"次の表は、5店舗の今月の売上高(万円)である。\n渋谷:320　新宿:280　池袋:350　上野:260　品川:290\n5店舗の売上高の平均はいくらか。", choices:["290万円","300万円","310万円","320万円"], answer:1, exp:"合計1500万円÷5=300万円。" },
  { q:"次の表は、ある商品の月別販売個数である。\n1月:60個　2月:75個　3月:90個　4月:80個\n前月比で販売個数が減少したのはどの月か。", choices:["2月","3月","4月","減少はない"], answer:2, exp:"1月→2月+15個、2月→3月+15個、3月→4月-10個。減少したのは4月。" },
  { q:"次の表は、あるクラスの通学時間の分布である。\n15分未満:8人　15〜29分:16人　30〜44分:10人　45分以上:4人\nこのクラスの人数は全部で何人か。", choices:["40人","34人","36人","38人"], answer:3, exp:"8+16+10+4=38人。" },
  { q:"次の表は、ある会社の年代別従業員数である。\n20代:35人　30代:52人　40代:30人　50代以上:15人\n30代の従業員が全体に占める割合は約何%か(小数点以下四捨五入)。", choices:["40%","44%","32%","36%"], answer:0, exp:"全体132人のうち30代52人。52/132≈39.4%で四捨五入すると約40%。" },
  { q:"次の表は、4半期ごとのある製品の販売数(個)である。\n第1四半期:1200　第2四半期:1450　第3四半期:1380　第4四半期:1600\n年間の総販売数はいくらか。", choices:["5530個","5630個","5730個","5430個"], answer:1, exp:"1200+1450+1380+1600=5630個。" },
  { q:"次の表は、あるレストランのメニュー別注文数の割合である。\nパスタ:30%　ピザ:25%　サラダ:20%　その他:25%\nパスタとピザを合わせた注文割合は全体の何%か。", choices:["45%","50%","55%","60%"], answer:2, exp:"30+25=55%。" },
  { q:"次の表は、ある市の月別降水量(mm)である。\n6月:180mm　7月:240mm　8月:150mm　9月:200mm\n最も降水量が多かった月と少なかった月の差は何mmか。", choices:["60mm","70mm","80mm","90mm"], answer:3, exp:"最多240mm(7月)、最少150mm(8月)。240-150=90mm。" },
  { q:"次の表は、あるアンケートの満足度の内訳(合計200人)である。\n満足:86人　やや満足:64人　やや不満:32人　不満:18人\n「満足」「やや満足」を合わせた割合は全体の何%か。", choices:["75%","80%","85%","70%"], answer:0, exp:"(86+64)/200=150/200=0.75=75%。" },
  { q:"次の表は、ある学校の部活動別加入者数である。\n運動部:210人　文化部:150人　委員会のみ:40人\n運動部と文化部の加入者数の差は何人か。", choices:["50人","60人","70人","80人"], answer:1, exp:"210-150=60人。" },
  { q:"次の表は、あるオンライン講座の年代別受講者数(人)である。\n10代:40　20代:128　30代:96　40代以上:56\n受講者全体に占める20代の割合は何%か。", choices:["30%","36%","40%","44%"], answer:2, exp:"合計320人のうち20代128人。128/320=0.4=40%。" },
  { q:"次の表は、ある月のアルバイトA〜Dの勤務時間(時間)である。\nA:32　B:28　C:40　D:24\n勤務時間が最も長い人と最も短い人の差は何時間か。", choices:["18時間","12時間","14時間","16時間"], answer:3, exp:"最長40時間(C)、最短24時間(D)。40-24=16時間。" },
  { q:"次の表は、ある店舗の曜日別来客数である。\n月:80人　火:75人　水:90人　木:85人　金:120人　土:200人　日:180人\n1週間の来客数の合計は何人か。", choices:["830人","860人","890人","800人"], answer:0, exp:"80+75+90+85+120+200+180=830人。" },
  { q:"次の表は、ある試験の得点分布(合計50人)である。\n90点以上:8人　70〜89点:22人　50〜69点:15人　49点以下:5人\n70点以上の人数は全体の何%か。", choices:["56%","60%","64%","50%"], answer:1, exp:"(8+22)/50=30/50=0.6=60%。" },
  { q:"次の表は、あるチェーン店の地域別店舗数である。\n関東:45店　関西:28店　中部:18店　その他:9店\n全店舗数に占める関東の割合は約何%か(小数点以下四捨五入)。", choices:["55%","40%","45%","50%"], answer:2, exp:"合計100店のうち関東45店。45/100=45%。" },
  { q:"次の表は、ある会社の月別残業時間の合計(時間)である。\n4月:120　5月:150　6月:100　7月:180\n4か月間の月平均残業時間はいくらか。", choices:["140時間","145時間","125時間","137.5時間"], answer:3, exp:"合計550時間÷4=137.5時間。" },
  { q:"次の表は、ある動物園の来場者数(人)である。\n平日平均:800人/日　休日平均:2200人/日\n平日5日・休日2日からなる1週間の来場者数の合計は何人か。", choices:["8400人","9000人","9600人","7800人"], answer:0, exp:"800×5+2200×2=4000+4400=8400人。" },
  { q:"次の表は、あるスーパーの部門別売上高(万円)である。\n青果:180　精肉:220　鮮魚:150　惣菜:130　その他:120\n売上高が最も高い部門と最も低い部門の差は何万円か。", choices:["90万円","100万円","70万円","80万円"], answer:1, exp:"最高220万円(精肉)、最低120万円(その他)。220-120=100万円。" }
]},
{ group:"非言語", id:"kuuranhyou", name:"図表の空欄推測", desc:"表の中の空欄の数値を推測する", questions:[
  { q:"ある店の商品別売上個数(合計100個)である。\nA:32個　B:28個　C:?個　D:18個\nCに入る数字はいくつか。", choices:["22個","24個","26個","20個"], answer:0, exp:"100-32-28-18=22個。" },
  { q:"ある学年の組別人数(合計120人)である。\n1組:30人　2組:?人　3組:28人　4組:32人\n2組に入る数字はいくつか。", choices:["28人","30人","32人","26人"], answer:1, exp:"120-30-28-32=30人。" },
  { q:"ある施設の月別来場者数の推移である。毎月一定数ずつ増加しているとする。\n1月:200人　2月:240人　3月:?人　4月:320人\n3月に入る数字はいくつか。", choices:["260人","270人","280人","300人"], answer:2, exp:"毎月40人ずつ増加しているので、3月は240+40=280人。" },
  { q:"ある工場の週別生産数と不良率である。不良率はどちらの週も2%で一定とする。\n1週目:生産500個、不良10個(不良率2%)\n2週目:生産?個、不良12個(不良率2%)\n2週目の生産数はいくつか。", choices:["650個","700個","550個","600個"], answer:3, exp:"不良率2%=12÷生産個数より、生産個数=12÷0.02=600個。" },
  { q:"ある店舗の売上構成比(合計100%)である。\n食品:40%　日用品:25%　衣料品:?%　その他:15%\n衣料品に入る数字はいくつか。", choices:["20%","25%","30%","15%"], answer:0, exp:"100-40-25-15=20%。" },
  { q:"ある会社の四半期売上(百万円)で、各四半期は前期比で一定の倍率で増加している。\n第1四半期:100　第2四半期:110　第3四半期:?　第4四半期:133.1\n第3四半期に入る数字はいくつか。", choices:["120","121","115","118"], answer:1, exp:"各四半期は前期の1.1倍。第3四半期=110×1.1=121。(121×1.1=133.1で第4四半期と一致)" },
  { q:"ある試験の得点分布(合計40人)である。\n90点以上:5人　70〜89点:?人　50〜69点:12人　49点以下:3人\n70〜89点に入る数字はいくつか。", choices:["24人","18人","20人","22人"], answer:2, exp:"40-5-12-3=20人。" },
  { q:"ある商品の在庫推移(個)である。\n月初在庫100個、入荷80個、出荷?個、月末在庫60個\n出荷に入る数字はいくつか。", choices:["140個","100個","110個","120個"], answer:3, exp:"100+80-出荷=60より、出荷=120個。" },
  { q:"ある部署の残業時間(合計80時間、4人)である。\nAさん:25時間　Bさん:18時間　Cさん:?時間　Dさん:15時間\nCさんに入る数字はいくつか。", choices:["22時間","24時間","18時間","20時間"], answer:0, exp:"80-25-18-15=22時間。" },
  { q:"ある店舗の4月の客単価を求める表である。\n4月:売上300,000円、客数200人、客単価?円\n客単価に入る数字はいくつか。", choices:["1400円","1500円","1600円","1200円"], answer:1, exp:"300000÷200=1500円。" },
  { q:"ある店の商品別売上個数(合計90個)である。\nA:24個　B:19個　C:?個　D:22個\nCに入る数字はいくつか。", choices:["21個","23個","25個","27個"], answer:2, exp:"90-24-19-22=25個。" },
  { q:"ある学年の組別人数(合計140人)である。\n1組:33人　2組:?人　3組:35人　4組:38人\n2組に入る数字はいくつか。", choices:["36人","30人","32人","34人"], answer:3, exp:"140-33-35-38=34人。" },
  { q:"ある施設の月別来場者数の推移である。毎月一定数ずつ減少しているとする。\n1月:500人　2月:460人　3月:?人　4月:380人\n3月に入る数字はいくつか。", choices:["420人","440人","450人","400人"], answer:0, exp:"毎月40人ずつ減少しているので、3月は460-40=420人。" },
  { q:"ある工場の週別生産数と不良率である。不良率はどちらの週も4%で一定とする。\n1週目:生産300個、不良12個(不良率4%)\n2週目:生産?個、不良18個(不良率4%)\n2週目の生産数はいくつか。", choices:["400個","450個","500個","550個"], answer:1, exp:"不良率4%=18÷生産個数より、生産個数=18÷0.04=450個。" },
  { q:"ある店舗の売上構成比(合計100%)である。\n食品:35%　日用品:?%　衣料品:22%　その他:18%\n日用品に入る数字はいくつか。", choices:["35%","20%","25%","30%"], answer:2, exp:"100-35-22-18=25%。" },
  { q:"ある会社の四半期売上(百万円)で、各四半期は前期比で一定の倍率で増加している。\n第1四半期:200　第2四半期:220　第3四半期:?　第4四半期:266.2\n第3四半期に入る数字はいくつか。", choices:["246","230","238","242"], answer:3, exp:"各四半期は前期の1.1倍。第3四半期=220×1.1=242。(242×1.1=266.2で第4四半期と一致)" },
  { q:"ある試験の得点分布(合計60人)である。\n90点以上:9人　70〜89点:?人　50〜69点:22人　49点以下:6人\n70〜89点に入る数字はいくつか。", choices:["23人","25人","27人","21人"], answer:0, exp:"60-9-22-6=23人。" },
  { q:"ある商品の在庫推移(個)である。\n月初在庫150個、入荷120個、出荷?個、月末在庫90個\n出荷に入る数字はいくつか。", choices:["170個","180個","150個","160個"], answer:1, exp:"150+120-出荷=90より、出荷=180個。" },
  { q:"ある部署の残業時間(合計95時間、5人)である。\nAさん:22時間　Bさん:18時間　Cさん:?時間　Dさん:20時間　Eさん:15時間\nCさんに入る数字はいくつか。", choices:["24時間","18時間","20時間","22時間"], answer:2, exp:"95-22-18-20-15=20時間。" },
  { q:"ある店舗の5月の客単価を求める表である。\n5月:売上450,000円、客数300人、客単価?円\n客単価に入る数字はいくつか。", choices:["1600円","1300円","1400円","1500円"], answer:3, exp:"450000÷300=1500円。" },
  { q:"ある工場の月別出荷数(合計2400個、4か月)である。\n1月:550個　2月:?個　3月:600個　4月:620個\n2月に入る数字はいくつか。", choices:["630個","650個","580個","600個"], answer:0, exp:"2400-550-600-620=630個。" },
  { q:"あるクラスの科目別平均点(合計、5科目)である。\n国語:68　数学:72　英語:?　理科:65　社会:70　5科目合計:350\n英語に入る数字はいくつか。", choices:["72","75","78","70"], answer:1, exp:"350-68-72-65-70=75。" },
  { q:"ある店の年齢層別来店者数(合計160人)である。\n10代:20人　20代:55人　30代:?人　40代以上:45人\n30代に入る数字はいくつか。", choices:["30人","35人","40人","45人"], answer:2, exp:"160-20-55-45=40人。" },
  { q:"ある倉庫の月次在庫表である。\n月初500個、入庫?個、出庫420個、月末在庫380個\n入庫に入る数字はいくつか。", choices:["320個","340個","280個","300個"], answer:3, exp:"500+入庫-420=380より、入庫=300個。" },
  { q:"あるレース参加者のタイム分布(合計45人)である。\n30分未満:12人　30〜39分:?人　40〜49分:14人　50分以上:5人\n30〜39分に入る数字はいくつか。", choices:["14人","16人","18人","12人"], answer:0, exp:"45-12-14-5=14人。" },
  { q:"ある会社の月別新規契約数の推移である。毎月一定数ずつ増加しているとする。\n1月:80件　2月:95件　3月:?件　4月:125件\n3月に入る数字はいくつか。", choices:["105件","110件","115件","100件"], answer:1, exp:"毎月15件ずつ増加しているので、3月は95+15=110件。" },
  { q:"ある学校の男女別生徒数(合計280人)である。\n男子:?人　女子:132人\n男子に入る数字はいくつか。", choices:["138人","144人","148人","152人"], answer:2, exp:"280-132=148人。" },
  { q:"ある喫茶店のドリンク別注文数(合計200杯)である。\nコーヒー:88杯　紅茶:?杯　ジュース:42杯　その他:30杯\n紅茶に入る数字はいくつか。", choices:["44杯","48杯","36杯","40杯"], answer:3, exp:"200-88-42-30=40杯。" },
  { q:"あるジムの時間帯別利用者数(合計120人)である。\n午前:28人　午後:?人　夜間:46人\n午後に入る数字はいくつか。", choices:["46人","50人","36人","42人"], answer:0, exp:"120-28-46=46人。" },
  { q:"ある野菜の月別出荷量(合計580kg、4か月)である。\n1月:140kg　2月:150kg　3月:?kg　4月:160kg\n3月に入る数字はいくつか。", choices:["120kg","130kg","140kg","150kg"], answer:1, exp:"580-140-150-160=130kg。" }
]},
{ group:"非言語", id:"seisan", name:"代金精算", desc:"複数人での立替・割り勘の精算", questions:[
  { q:"A,B,Cの3人で旅行し、宿泊費30,000円をAが立て替えた。3人で均等に負担する場合、BとCはそれぞれAにいくら支払えばよいか。", choices:["10000円","15000円","20000円","7500円"], answer:0, exp:"30000÷3=10000円ずつ。" },
  { q:"A,B,Cの3人で食事をし、合計12,000円をBが支払った。均等に割り勘する場合、AとCはBにそれぞれいくら渡せばよいか。", choices:["3000円","4000円","5000円","6000円"], answer:1, exp:"12000÷3=4000円ずつ。" },
  { q:"A,B,Cの3人でタクシーに乗り、運賃3,600円をAが支払った。均等に負担する場合、BはAにいくら支払えばよいか。", choices:["1800円","1000円","1200円","1500円"], answer:2, exp:"3600÷3=1200円。" },
  { q:"A,B,C,Dの4人でキャンプ用品を購入し、合計16,000円をAが立て替えた。均等に負担する場合、B,C,Dはそれぞれいくらずつ支払えばよいか。", choices:["4500円","5000円","3500円","4000円"], answer:3, exp:"16000÷4=4000円ずつ。" },
  { q:"A,Bの2人で旅行に行き、Aが交通費8,000円、Bが宿泊費14,000円を支払った。総額を折半する場合、どちらがいくら支払うべきか。", choices:["BがAに3000円渡す","AがBに3000円渡す","BがAに5000円渡す","AがBに5000円渡す"], answer:0, exp:"総額22000円を折半すると11000円ずつ。Aは8000円払い済みなので不足分3000円をBがAに渡す。" },
  { q:"A,B,Cの3人で共同購入したプレゼント代9,000円をCが全額支払った。A,BはそれぞれCにいくら支払えばよいか。", choices:["2000円","3000円","3600円","4500円"], answer:1, exp:"9000÷3=3000円ずつ。" },
  { q:"A,B,C,Dの4人で飲み会を行い、合計代金は20,000円だった。Aが幹事として全額を立て替えた。Dは飲み放題を利用せず、他の3人より2,000円少ない負担額とする。Dの支払い額はいくらか。", choices:["5000円","3000円","3500円","4000円"], answer:2, exp:"他3人の負担額をxとすると3x+(x-2000)=20000より、x=5500円。Dの負担額=5500-2000=3500円。" },
  { q:"A,B,Cの3人で旅行費用を精算する。Aは15,000円、Bは9,000円、Cは0円を支払った。合計24,000円を3人で均等負担する場合、Cは最終的に合計いくら支払う必要があるか。", choices:["9000円","6000円","7000円","8000円"], answer:3, exp:"1人あたり負担額=24000÷3=8000円。Cはまだ支払っていないため8000円が必要。" },
  { q:"A,B,Cの3人でレンタカーを借り、料金15,000円をAが支払った。使用割合をA:B:C=3:2:1で負担する場合、Cの負担額はいくらか。", choices:["2500円","3000円","5000円","2000円"], answer:0, exp:"比の合計6。Cの負担=15000×1/6=2500円。" },
  { q:"A,B,Cの3人で共同で機材をレンタルし、レンタル料18,000円をBが立て替えた。使用時間の比がA:B:C=2:3:4である場合、Aの負担額はいくらか。", choices:["2000円","4000円","6000円","8000円"], answer:1, exp:"比の合計9。Aの負担=18000×2/9=4000円。" },
  { q:"A,B,Cの3人で旅行し、宿泊費45,000円をAが立て替えた。3人で均等に負担する場合、BとCはそれぞれAにいくら支払えばよいか。", choices:["12000円","13500円","15000円","18000円"], answer:2, exp:"45000÷3=15000円ずつ。" },
  { q:"A,B,Cの3人で食事をし、合計18,000円をBが支払った。均等に割り勘する場合、AとCはBにそれぞれいくら渡せばよいか。", choices:["7000円","8000円","5000円","6000円"], answer:3, exp:"18000÷3=6000円ずつ。" },
  { q:"A,B,Cの3人でタクシーに乗り、運賃4,500円をAが支払った。均等に負担する場合、BはAにいくら支払えばよいか。", choices:["1500円","2000円","2500円","1000円"], answer:0, exp:"4500÷3=1500円。" },
  { q:"A,B,C,Dの4人でキャンプ用品を購入し、合計24,000円をAが立て替えた。均等に負担する場合、B,C,Dはそれぞれいくらずつ支払えばよいか。", choices:["5500円","6000円","6500円","5000円"], answer:1, exp:"24000÷4=6000円ずつ。" },
  { q:"A,Bの2人で旅行に行き、Aが交通費12,000円、Bが宿泊費20,000円を支払った。総額を折半する場合、どちらがいくら支払うべきか。", choices:["BがAに6000円渡す","AがBに6000円渡す","BがAに4000円渡す","AがBに4000円渡す"], answer:2, exp:"総額32000円を折半すると16000円ずつ。Aは12000円払い済みなので不足分4000円をBがAに渡す。" },
  { q:"A,B,Cの3人で共同購入したプレゼント代13,500円をCが全額支払った。A,BはそれぞれCにいくら支払えばよいか。", choices:["5000円","3500円","4000円","4500円"], answer:3, exp:"13500÷3=4500円ずつ。" },
  { q:"A,B,C,Dの4人で飲み会を行い、合計代金は26,000円だった。Aが幹事として全額を立て替えた。Dは飲み放題を利用せず、他の3人より2,000円少ない負担額とする。Dの支払い額はいくらか。", choices:["5000円","5500円","6000円","4500円"], answer:0, exp:"他3人の負担額をxとすると3x+(x-2000)=26000より、4x=28000、x=7000円。Dの負担額=7000-2000=5000円。" },
  { q:"A,B,Cの3人で旅行費用を精算する。Aは18,000円、Bは12,000円、Cは0円を支払った。合計30,000円を3人で均等負担する場合、Cは最終的に合計いくら支払う必要があるか。", choices:["9000円","10000円","11000円","8000円"], answer:1, exp:"1人あたり負担額=30000÷3=10000円。Cはまだ支払っていないため10000円が必要。" },
  { q:"A,B,Cの3人でレンタカーを借り、料金21,000円をAが支払った。使用割合をA:B:C=4:2:1で負担する場合、Cの負担額はいくらか。", choices:["2000円","2500円","3000円","3500円"], answer:2, exp:"比の合計7。Cの負担=21000×1/7=3000円。" },
  { q:"A,B,Cの3人で共同で機材をレンタルし、レンタル料24,000円をBが立て替えた。使用時間の比がA:B:C=3:4:5である場合、Aの負担額はいくらか。", choices:["7000円","8000円","5000円","6000円"], answer:3, exp:"比の合計12。Aの負担=24000×3/12=6000円。" },
  { q:"A,B,Cの3人で旅行に行き、合計費用は45,000円だった。Aが30,000円、Bが15,000円を支払い、Cは何も支払っていない。均等精算する場合、Cが支払うべき合計額はいくらか。", choices:["15000円","18000円","10000円","12000円"], answer:0, exp:"1人あたり負担額=45000÷3=15000円。Cはまだ支払っていないため、合計15000円を支払う必要がある。" },
  { q:"A,Bの2人でスキー旅行に行き、Aがリフト券代16,000円、Bが宿泊費24,000円を支払った。総額を折半する場合、精算後の受け渡し額はいくらか。", choices:["AがBに4000円渡す","BがAに4000円渡す","AがBに8000円渡す","BがAに8000円渡す"], answer:1, exp:"総額40000円を折半すると20000円ずつ。Aは16000円払い済みで4000円不足。BがAに4000円渡す。" },
  { q:"A,B,C,Dの4人で合計32,000円の買い物をした。Aが全額を立て替え、使用割合をA:B:C:D=1:1:1:1(均等)とする場合、B,C,Dがそれぞれ支払う額はいくらか。", choices:["6000円","7000円","8000円","9000円"], answer:2, exp:"32000÷4=8000円ずつ。" },
  { q:"A,B,Cの3人で共同で家電製品を購入し、代金36,000円をAが立て替えた。3人で均等に負担する場合、B,Cが支払う合計額はいくらか。", choices:["18000円","20000円","22000円","24000円"], answer:3, exp:"1人あたり36000÷3=12000円。BとCの合計は12000×2=24000円。" },
  { q:"A,B,Cの3人で旅行に行き、Aが宿泊費25,000円、Bが交通費11,000円、Cが食費9,000円を支払った。総額を均等に精算する場合、1人あたりの負担額はいくらか。", choices:["15000円","12000円","13000円","14000円"], answer:0, exp:"合計45000円÷3=15000円。" },
  { q:"A,Bの2人が共同で工具を購入し、合計14,000円をAが支払った。使用頻度の比A:B=5:2で負担する場合、Bの負担額はいくらか。", choices:["3000円","4000円","5000円","2000円"], answer:1, exp:"比の合計7。Bの負担=14000×2/7=4000円。" },
  { q:"A,B,Cの3人で合宿費用45,000円を、A:B:C=3:3:4の割合で負担することにした。Cの負担額はいくらか。", choices:["16000円","17000円","18000円","19000円"], answer:2, exp:"比の合計10。Cの負担=45000×4/10=18000円。" },
  { q:"A,B,Cの3人でスポーツ観戦に行き、チケット代合計27,000円をCが立て替えた。A,Bはそれぞれ均等に負担する場合、AがCに支払う額はいくらか。", choices:["10000円","7000円","8000円","9000円"], answer:3, exp:"27000÷3=9000円ずつ。" },
  { q:"A,B,Cの3人でホテルの部屋代36,000円を、宿泊日数の比A:B:C=2:3:4で負担することにした。Aの負担額はいくらか。", choices:["8000円","10000円","12000円","6000円"], answer:0, exp:"比の合計9。Aの負担=36000×2/9=8000円。" },
  { q:"A,Bの2人で共同購入した自転車の修理代8,000円をBが立て替えた。使用頻度の比A:B=3:1で負担する場合、Aの負担額はいくらか。", choices:["5000円","6000円","7000円","4000円"], answer:1, exp:"比の合計4。Aの負担=8000×3/4=6000円。" }
]},
{ group:"非言語", id:"shigoto", name:"仕事算", desc:"作業効率や分割払いに関する計算", questions:[
  { q:"ある仕事をAが1人で行うと12日、Bが1人で行うと18日かかる。2人で一緒に行うと何日で終わるか。", choices:["7.2日","8日","9日","6日"], answer:0, exp:"1/12+1/18=5/36。日数=36/5=7.2日。" },
  { q:"ある仕事をAだけで行うと20日、Bだけで行うと30日かかる。2人で5日間一緒に作業した後、残りをAが1人で仕上げるには何日かかるか。", choices:["約10日","約11.7日","約13日","約9日"], answer:1, exp:"2人5日分=5×(1/20+1/30)=5/12。残り7/12をAが行うと(7/12)÷(1/20)=約11.7日。" },
  { q:"総額60,000円の商品を分割払いで購入する。頭金として全体の20%を支払い、残りを12回の均等払いにする場合、1回あたりの支払額はいくらか。", choices:["5000円","3600円","4000円","4500円"], answer:2, exp:"頭金12000円、残り48000円。48000÷12=4000円。" },
  { q:"ある水槽を満水にするのに、給水管Aだけでは6時間、給水管Bだけでは8時間かかる。AとBを同時に使うと何時間で満水になるか。", choices:["約4時間","3時間","5時間","約3.4時間"], answer:3, exp:"1/6+1/8=7/24。時間=24/7≈3.4時間。" },
  { q:"総額150,000円の商品を購入する。手数料5,000円を含めた総支払額を10回均等払いにする場合、1回あたりの支払額はいくらか。", choices:["15500円","16000円","14500円","15000円"], answer:0, exp:"総支払額=150000+5000=155000円。155000÷10=15500円。" },
  { q:"ある仕事をA,B,Cの3人で行うと5日で終わる。Aだけで行うと10日、Bだけで行うと15日かかる。Cだけで行うとこの仕事は何日で終わるか。", choices:["25日","30日","35日","20日"], answer:1, exp:"3人の合計仕事率=1/5。A+Bの仕事率=1/10+1/15=1/6。C=1/5-1/6=1/30。C単独で30日。" },
  { q:"総額150,000円の商品を頭金30,000円を支払ったあと、残りを24回の均等払いで支払う場合、1回あたりの支払額はいくらか。", choices:["6000円","4500円","5000円","5500円"], answer:2, exp:"残額120000円÷24=5000円。" },
  { q:"ある印刷作業をAだけで行うと8時間、A,B2人で行うと3時間かかる。Bだけでこの作業を行うと何時間かかるか。", choices:["5時間","5.5時間","4時間","4.8時間"], answer:3, exp:"1/8+1/B=1/3より1/B=5/24。B=24/5=4.8時間。" },
  { q:"200,000円の商品を分割払いで購入する。初回は総額の25%を支払い、残りを均等に8回で支払う場合、2回目以降の1回あたりの支払額はいくらか。", choices:["18750円","19000円","20000円","17500円"], answer:0, exp:"初回50000円、残り150000円。150000÷8=18750円。" },
  { q:"ある仕事をAが3日、続けてBが4日行うと仕事が完了する。Aだけで行うと9日かかる場合、Bだけで行うとこの仕事は何日で終わるか。", choices:["12日","6日","8日","10日"], answer:1, exp:"Aの1日の仕事率1/9。3日分で1/3。残り2/3をBが4日で行ったので、Bの1日の仕事率=(2/3)/4=1/6。Bだけなら6日。" },
  { q:"ある仕事をAが1人で行うと15日、Bが1人で行うと10日かかる。2人で一緒に行うと何日で終わるか。", choices:["8日","5日","6日","7日"], answer:2, exp:"1/15+1/10=1/6。日数=6日。" },
  { q:"ある仕事をAだけで行うと24日、Bだけで行うと40日かかる。2人で6日間一緒に作業した後、残りをBが1人で仕上げるには何日かかるか。", choices:["18日","20日","22日","24日"], answer:3, exp:"2人6日分=6×(1/24+1/40)=6×8/120=2/5。残り3/5をBが行うと(3/5)÷(1/40)=24日。" },
  { q:"総額80,000円の商品を分割払いで購入する。頭金として全体の25%を支払い、残りを10回の均等払いにする場合、1回あたりの支払額はいくらか。", choices:["6000円","7000円","8000円","5000円"], answer:0, exp:"頭金20000円、残り60000円。60000÷10=6000円。" },
  { q:"ある水槽を満水にするのに、給水管Aだけでは4時間、給水管Bだけでは12時間かかる。AとBを同時に使うと何時間で満水になるか。", choices:["2時間","3時間","4時間","5時間"], answer:1, exp:"1/4+1/12=1/3。時間=3時間。" },
  { q:"総額200,000円の商品を購入する。手数料8,000円を含めた総支払額を8回均等払いにする場合、1回あたりの支払額はいくらか。", choices:["28000円","25000円","26000円","27000円"], answer:2, exp:"総支払額=200000+8000=208000円。208000÷8=26000円。" },
  { q:"ある仕事をA,B,Cの3人で行うと4日で終わる。Aだけで行うと12日、Bだけで行うと8日かかる。Cだけで行うとこの仕事は何日で終わるか。", choices:["26日","20日","22日","24日"], answer:3, exp:"3人の合計仕事率=1/4。A+Bの仕事率=1/12+1/8=5/24。C=1/4-5/24=1/24。C単独で24日。" },
  { q:"総額180,000円の商品を頭金40,000円を支払ったあと、残りを20回の均等払いで支払う場合、1回あたりの支払額はいくらか。", choices:["7000円","7500円","6000円","6500円"], answer:0, exp:"残額140000円÷20=7000円。" },
  { q:"ある印刷作業をAだけで行うと10時間、A,B2人で行うと4時間かかる。Bだけでこの作業を行うと何時間かかるか。", choices:["約6.2時間","約6.7時間","約7.1時間","約7.5時間"], answer:1, exp:"1/10+1/B=1/4より1/B=3/20。B=20/3≈6.7時間。" },
  { q:"300,000円の商品を分割払いで購入する。初回は総額の30%を支払い、残りを均等に7回で支払う場合、2回目以降の1回あたりの支払額はいくらか。", choices:["34000円","28000円","30000円","32000円"], answer:2, exp:"初回90000円、残り210000円。210000÷7=30000円。" },
  { q:"ある仕事をAが4日、続けてBが6日行うと仕事が完了する。Aだけで行うと12日かかる場合、Bだけで行うとこの仕事は何日で終わるか。", choices:["10日","11日","12日","9日"], answer:3, exp:"Aの1日の仕事率1/12。4日分で1/3。残り2/3をBが6日で行ったので、Bの1日の仕事率=(2/3)/6=1/9。Bだけなら9日。" },
  { q:"ある水槽が満水の状態から、排水管Aだけで排水すると10時間、排水管A,B両方使うと4時間で空になる。排水管Bだけで排水すると何時間かかるか。", choices:["約6.7時間","7時間","約7.5時間","約6.2時間"], answer:0, exp:"1/10+1/B=1/4より1/B=3/20。B=20/3≈6.7時間。" },
  { q:"ある仕事をAが1人で行うと20日、Bが1人で行うと30日、Cが1人で行うと60日かかる。3人で一緒に行うと何日で終わるか。", choices:["9日","10日","11日","8日"], answer:1, exp:"1/20+1/30+1/60=3/60+2/60+1/60=6/60=1/10。日数=10日。" },
  { q:"総額240,000円の家電を分割払いで購入する。頭金なしで15回均等払いにする場合、1回あたりの支払額はいくらか。", choices:["14000円","15000円","16000円","17000円"], answer:2, exp:"240000÷15=16000円。" },
  { q:"ある仕事をAだけで行うと18日、A,B2人で行うと8日かかる。この仕事をBだけで行うと何日かかるか。", choices:["約15.4日","約12.4日","約13.4日","約14.4日"], answer:3, exp:"1/18+1/B=1/8より1/B=1/8-1/18=5/72。B=72/5=14.4日。" },
  { q:"ある仕事をA,Bの2人で行うと6日、Aだけで行うと10日かかる。Bだけで行うとこの仕事は何日で終わるか。", choices:["15日","12日","13日","14日"], answer:0, exp:"1/6-1/10=1/15。Bだけなら15日。" },
  { q:"360,000円の車の修理代を分割払いで支払う。初回に総額の40%を支払い、残りを均等に6回で支払う場合、1回あたりの支払額はいくらか。", choices:["34000円","36000円","30000円","32000円"], answer:1, exp:"初回144000円、残り216000円。216000÷6=36000円。" },
  { q:"ある倉庫の在庫整理をAが1人で行うと8時間、Bが1人で行うと24時間かかる。2人で一緒に行うと何時間で終わるか。", choices:["4時間","5時間","6時間","7時間"], answer:2, exp:"1/8+1/24=3/24+1/24=4/24=1/6。時間=6時間。" },
  { q:"ある仕事をAだけで行うと18日、Bだけで行うと9日かかる。2人で一緒に行うと何日で終わるか。", choices:["7日","4日","5日","6日"], answer:3, exp:"1/18+1/9=3/18=1/6。日数=6日。" },
  { q:"ある仕事をAだけで行うと16日、Bだけで行うと48日かかる。2人で一緒に行うと何日で終わるか。", choices:["12日","14日","16日","10日"], answer:0, exp:"1/16+1/48=3/48+1/48=4/48=1/12。日数=12日。" },
  { q:"総額90,000円の商品を頭金なしで、6回の均等払いで購入する場合、1回あたりの支払額はいくらか。", choices:["14000円","15000円","12000円","13000円"], answer:1, exp:"90000÷6=15000円。" }
]},
{ group:"非言語", id:"nagare", name:"物の流れ", desc:"在庫や物流に関する問題", questions:[
  { q:"ある倉庫に商品が月初300個あった。月間で入荷450個、出荷380個があった場合、月末の在庫は何個か。", choices:["370個","400個","320個","350個"], answer:0, exp:"300+450-380=370個。" },
  { q:"ある店舗の在庫は週初200個。週の間に仕入れが50個、30個、70個あった。週末の在庫が280個だった場合、この週に売れた商品は何個か。", choices:["60個","70個","80個","90個"], answer:1, exp:"200+150-280=70個。" },
  { q:"ある工場では1日に製品を500個生産し、そのうち出荷は1日450個である。生産開始時の在庫が0個だったとき、10日後の在庫は何個か。", choices:["400個","450個","500個","550個"], answer:2, exp:"1日あたり増加50個。10日で500個。" },
  { q:"ある物流センターでは、月初在庫が1,200個、月間入庫が2,800個、月間出庫が3,500個だった。月末在庫は何個か。", choices:["600個","700個","400個","500個"], answer:3, exp:"1200+2800-3500=500個。" },
  { q:"ある小売店で商品Aの1日の平均販売数は20個である。現在の在庫が140個のとき、追加発注をしない場合、あと何日で在庫が尽きるか。", choices:["7日","8日","5日","6日"], answer:0, exp:"140÷20=7日。" },
  { q:"ある倉庫では月初在庫800個で、月間入庫が月間出庫より300個少なかった。月末在庫は何個か。", choices:["400個","500個","600個","300個"], answer:1, exp:"800-300=500個。" },
  { q:"ある店舗チェーンでA店からB店へ商品150個を移送した。移送前のA店在庫は500個、B店在庫は200個だった。移送後のA店とB店の在庫はそれぞれ何個か。", choices:["A店300個・B店400個","A店350個・B店250個","A店350個・B店350個","A店400個・B店250個"], answer:2, exp:"A店=500-150=350個、B店=200+150=350個。" },
  { q:"ある工場の生産ラインでは、1時間あたり80個生産し、そのうち5%が不良品として廃棄される。8時間稼働した場合、良品は何個生産されるか。", choices:["620個","592個","600個","608個"], answer:3, exp:"80×8=640個。良品は95%なので640×0.95=608個。" },
  { q:"ある商品は発注してから届くまでに5日かかる。1日の平均販売数が15個のとき、在庫切れを起こさずに発注すべき在庫水準(発注点)はいくつか。", choices:["75個","90個","100個","60個"], answer:0, exp:"発注点=1日販売数×リードタイム=15×5=75個。" },
  { q:"ある倉庫で先入れ先出し(FIFO)方式で在庫を管理している。月初在庫が旧ロット200個(単価100円)、月中に新ロット300個(単価120円)を仕入れた。月内に350個出荷した場合、FIFO方式での出荷原価はいくらか。", choices:["35000円","38000円","40000円","42000円"], answer:1, exp:"先に旧ロット200個×100円=20000円、残り150個は新ロット150個×120円=18000円。合計38000円。" },
  { q:"ある倉庫に商品が月初450個あった。月間で入荷620個、出荷580個があった場合、月末の在庫は何個か。", choices:["420個","450個","490個","520個"], answer:2, exp:"450+620-580=490個。" },
  { q:"ある店舗の在庫は週初150個。週の間に仕入れが40個、60個あった。週末の在庫が180個だった場合、この週に売れた商品は何個か。", choices:["80個","90個","60個","70個"], answer:3, exp:"150+100-180=70個。" },
  { q:"ある工場では1日に製品を600個生産し、そのうち出荷は1日520個である。生産開始時の在庫が0個だったとき、15日後の在庫は何個か。", choices:["1200個","1300個","1000個","1100個"], answer:0, exp:"1日あたり増加80個。15日で1200個。" },
  { q:"ある物流センターでは、月初在庫が2,000個、月間入庫が3,500個、月間出庫が4,200個だった。月末在庫は何個か。", choices:["1200個","1300個","1500個","1000個"], answer:1, exp:"2000+3500-4200=1300個。" },
  { q:"ある小売店で商品Bの1日の平均販売数は30個である。現在の在庫が270個のとき、追加発注をしない場合、あと何日で在庫が尽きるか。", choices:["7日","8日","9日","10日"], answer:2, exp:"270÷30=9日。" },
  { q:"ある倉庫では月初在庫1,200個で、月間入庫が月間出庫より450個少なかった。月末在庫は何個か。", choices:["850個","950個","650個","750個"], answer:3, exp:"1200-450=750個。" },
  { q:"ある店舗チェーンでC店からD店へ商品220個を移送した。移送前のC店在庫は600個、D店在庫は350個だった。移送後のC店とD店の在庫はそれぞれ何個か。", choices:["C店380個・D店570個","C店400個・D店550個","C店420個・D店530個","C店440個・D店510個"], answer:0, exp:"C店=600-220=380個、D店=350+220=570個。" },
  { q:"ある工場の生産ラインでは、1時間あたり120個生産し、そのうち3%が不良品として廃棄される。10時間稼働した場合、良品は何個生産されるか。", choices:["1140個","1164個","1200個","1236個"], answer:1, exp:"120×10=1200個。良品は97%なので1200×0.97=1164個。" },
  { q:"ある商品は発注してから届くまでに7日かかる。1日の平均販売数が12個のとき、在庫切れを起こさずに発注すべき在庫水準(発注点)はいくつか。", choices:["108個","70個","84個","96個"], answer:2, exp:"発注点=1日販売数×リードタイム=12×7=84個。" },
  { q:"ある倉庫で先入れ先出し(FIFO)方式で在庫を管理している。月初在庫が旧ロット150個(単価90円)、月中に新ロット250個(単価110円)を仕入れた。月内に300個出荷した場合、FIFO方式での出荷原価はいくらか。", choices:["31500円","33000円","28500円","30000円"], answer:3, exp:"先に旧ロット150個×90円=13500円、残り150個は新ロット150個×110円=16500円。合計30000円。" },
  { q:"ある倉庫の在庫回転率を求める。年間出荷量が2,400個、平均在庫数が200個のとき、在庫回転率(年間出荷量÷平均在庫数)はいくつか。", choices:["12回","14回","16回","10回"], answer:0, exp:"2400÷200=12回。" },
  { q:"ある店舗で商品Cの安全在庫を20個、リードタイム中の予想販売数を60個とするとき、発注点はいくつか。", choices:["70個","80個","90個","100個"], answer:1, exp:"発注点=安全在庫+リードタイム中の予想販売数=20+60=80個。" },
  { q:"ある工場で不良品率が2%の製品を1日500個生産している。1週間(7日間)で発生する不良品は何個か。", choices:["60個","65個","70個","75個"], answer:2, exp:"1日の不良品=500×0.02=10個。7日間で10×7=70個。" },
  { q:"ある物流倉庫でA地点からB地点へ400個、B地点からC地点へその半分を再出荷した。C地点に届いた個数は何個か。", choices:["220個","150個","180個","200個"], answer:3, exp:"400個の半分は200個。" },
  { q:"ある店の商品Dは、月初在庫80個、月間入荷150個、月間出荷210個だった場合、月末在庫は何個か。", choices:["20個","30個","40個","10個"], answer:0, exp:"80+150-210=20個。" },
  { q:"ある倉庫で商品Eの在庫が月初600個あり、月間で3回に分けて出荷され、それぞれ150個、120個、180個だった。月末の在庫は何個か。", choices:["120個","150個","180個","210個"], answer:1, exp:"600-(150+120+180)=600-450=150個。" },
  { q:"ある工場では2つのライン(1時間あたりそれぞれ90個、70個)で同時に生産している。6時間稼働したときの総生産数は何個か。", choices:["800個","900個","960個","1020個"], answer:2, exp:"(90+70)×6=960個。" },
  { q:"ある店舗で商品Fの発注リードタイムが4日、1日の平均販売数が25個、さらに需要変動に備えた安全在庫を30個確保する場合、発注点はいくつか。", choices:["100個","110個","120個","130個"], answer:3, exp:"発注点=25×4+30=130個。" },
  { q:"ある倉庫の年間出荷量が4,800個、在庫回転率が8回のとき、平均在庫数は何個か。", choices:["600個","700個","800個","500個"], answer:0, exp:"平均在庫数=年間出荷量÷在庫回転率=4800÷8=600個。" },
  { q:"ある店舗で商品Gの1日の平均販売数が18個、現在の在庫が126個ある。毎日18個ずつ販売されるとすると、在庫がちょうど0個になるのは何日後か。", choices:["6日後","7日後","8日後","9日後"], answer:1, exp:"126÷18=7日後。" }
]}
